from __future__ import annotations

from ..formal_model import FormalModel, ModelResult


def formal_model_markdown(model: FormalModel, result: ModelResult) -> str:
    lines = [
        "# Lifecycle Model",
        "",
        "> Generated by `./hfx generate`. Do not edit manually.",
        "",
        "This page lists the states, transitions, and rules that the lifecycle model checker",
        "covered, for engineers who change how leases, receiver connections, or lighting",
        "requests move through the bridge.",
        "",
        "The checker is written separately from the Rust state machines and visits every",
        "state of a small, reviewed model of leases, generations, transactions, delivery,",
        "and stable intent. It is not a hardware test.",
        "",
        "## What The Last Run Covered",
        "",
        f"- States: `{result.states}`",
        f"- Transition edges: `{result.transitions}`",
        f"- Maximum depth reached: `{result.maximum_depth_reached}`",
        f"- State bound: `{model.maximum_states}`",
        "",
        "## Covered Transitions",
        "",
    ]
    lines.extend(f"- `{name}`" for name in result.transition_names)
    lines.extend(["", "## Rules Checked In Every State", ""])
    lines.extend(f"- `{invariant}`" for invariant in model.invariant_ids)
    lines.append("")
    return "\n".join(lines)
